from openpyxl import load_workbook

wb = load_workbook('budget.xlsx', data_only=True)
total = 0.0
detail = []

for ws in wb.worksheets:
    rows = list(ws.iter_rows(values_only=True))
    if not rows:
        continue
    header = [str(h).strip().lower() if h is not None else '' for h in rows[0]]
    cat_idx = next((i for i, h in enumerate(header) if 'categor' in h), None)
    amt_idx = next((i for i, h in enumerate(header) if h in ('amount', 'expense', 'expenses', 'cost', 'budget', 'actual') or 'amount' in h or 'expense' in h), None)
    if cat_idx is not None and amt_idx is not None:
        for r in rows[1:]:
            if r[cat_idx] is None or r[amt_idx] is None:
                continue
            label = str(r[cat_idx]).strip().lower()
            if label in ('total', 'grand total', 'sum', '合计'):
                continue
            try:
                val = float(r[amt_idx])
            except (TypeError, ValueError):
                continue
            total += val
            detail.append((r[cat_idx], val))
    else:
        for r in rows:
            for v in r:
                pass  # non-standard layout; handle below by fallback scan

# Fallback: sum every numeric cell (excluding obvious total/label text columns)
if not detail:
    for ws in wb.worksheets:
        for row in ws.iter_rows(values_only=True):
            for v in row:
                if isinstance(v, (int, float)) and not isinstance(v, bool):
                    total += v

for name, val in detail:
    print(f"{name}: {val}")
print(f"TOTAL EXPENSES: {total}")

